// Production:
func acquire() -> CatalogLockResult {
    queue.sync {
        if fd >= 0 { return .acquired }   // re-entrant for the same process
        let opened = open(lockURL.path, O_CREAT | O_RDWR | O_CLOEXEC, 0o644)
        guard opened >= 0 else { return .unavailable(reason: "open failed") }
        if flock(opened, LOCK_EX | LOCK_NB) != 0 { close(opened); return .heldByAnother(owner: nil) }
        fd = opened
        return .acquired
    }
}

